INSERT INTO `roles` (`id`, `code`, `name_en`, `name_km`, `description`, `is_system`, `is_active`, `is_commission_eligible`, `can_assign_washer`, `can_assign_mechanic`, `created_at`, `updated_at`) VALUES ('2', 'cashier', 'Cashier', 'អ្នកគិតលុយ', 'Front-desk point of sale, order checkouts, payment receipts, order queue, and daily close registers.', '1', '1', '0', '0', '0', '2026-10-21 09:15:46', '2026-10-28 14:24:29');
INSERT INTO `roles` (`id`, `code`, `name_en`, `name_km`, `description`, `is_system`, `is_active`, `is_commission_eligible`, `can_assign_washer`, `can_assign_mechanic`, `created_at`, `updated_at`) VALUES ('3', 'washer', 'Washer', 'ជាងលាងរថយន្ត', 'Vehicle cleaning specialist: wash bay queue, active washing jobs, and commission earnings.', '1', '1', '1', '1', '0', '2026-10-21 09:15:46', '2026-10-28 14:24:29');
