INSERT INTO `upsell_rules` (`id`, `rule_uid`, `name`, `trigger_service_id`, `trigger_category`, `trigger_vehicle_type`, `trigger_min_mileage`, `offer_service_id`, `offer_product_id`, `offer_price_usd`, `offer_headline_en`, `offer_headline_km`, `offer_description_en`, `offer_description_km`, `is_active`, `created_at`) VALUES ('1', 'UPSELL-SUV-PREMIUM-WASH', 'Basic Wash on an SUV: offer Premium Wash for $5', '1', 'wash', 'suv_pickup', NULL, '3', NULL, '5.00', 'Special SUV Upgrade: Add Interior Detailing for only $5.00!', 'ការដំឡើងពិសេសសម្រាប់ SUV៖ បន្ថែមការសម្អាតខាងក្នុងត្រឹមតែ $5.00!', 'Upgrade this SUV to Full Wash (Exterior + Interior) at the exclusive promo rate of $5.00 (Standard: $8.50).', 'ដំឡើងការលាងរថយន្ត SUV នេះទៅកញ្ចប់ពេញលេញ (ក្រៅ + ក្នុង) ក្នុងតម្លៃពិសេស $5.00។', '1', '2026-10-28 14:08:20');
INSERT INTO `upsell_rules` (`id`, `rule_uid`, `name`, `trigger_service_id`, `trigger_category`, `trigger_vehicle_type`, `trigger_min_mileage`, `offer_service_id`, `offer_product_id`, `offer_price_usd`, `offer_headline_en`, `offer_headline_km`, `offer_description_en`, `offer_description_km`, `is_active`, `created_at`) VALUES ('2', 'UPSELL-HIGH-MILEAGE-SYNTHETIC', 'Conventional oil on a car over 75,000 km: recommend synthetic', NULL, 'engine_oil', NULL, '75000', NULL, '2', '42.00', 'High Mileage Care (>75,000 km): Upgrade to Full Synthetic Oil!', 'ការថែទាំចម្ងាយឆ្ងាយ (>75,000 គ.ម)៖ ដំឡើងទៅប្រើប្រេងសំយោគពេញលេញ!', 'Engines over 75,000 km benefit from advanced synthetic protection against wear, sludge, and heat breakdown.', 'ម៉ាស៊ីនដែលបើកបរលើសពី 75,000 គីឡូម៉ែត្រ ត្រូវការប្រេងសំយោគពេញលេញដើម្បីការពារការសឹករិចរិល។', '1', '2026-10-28 14:08:20');
